[ExtensionOf(classStr(RetailSalesOrderCalculator))]
public final class RetailSalesOrderCalculatorGlobalUnifiedPricing_Extension
{
    private Map setFoundPriceHistoryRecId;

}

Method.Source:
public void setPriceOnCurrentLine()
{
    next setPriceOnCurrentLine();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.UpdateGUPPriceAdjustmentHistory(crtSalesTransaction, this.crtLineIdCurrentLine);
    }
}

public void setDiscountOnCurrentLine()
{
    next setDiscountOnCurrentLine();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.UpdateGUPPriceAdjustmentHistory(crtSalesTransaction, this.crtLineIdCurrentLine);
    }
}

protected void saveSalesOrder()
{
    next saveSalesOrder();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.UpdateGUPPriceAdjustmentHistory(crtSalesTransaction);
    }
}

private void deleteMCRPriceHistory(SalesLine salesLine)
{
    MCRPriceHistory priceHistory;
    MCRPriceHistoryRef priceHistoryRef;

    ttsbegin;

    delete_from priceHistory
        exists join priceHistoryRef
        where priceHistory.RecId == priceHistoryRef.PriceHistoryRecId
           && priceHistoryRef.mcrOrderLine2PriceHistoryRef == salesLine.mcrOrderLine2PriceHistoryRef;

    delete_from priceHistoryRef
        where priceHistoryRef.mcrOrderLine2PriceHistoryRef == salesLine.mcrOrderLine2PriceHistoryRef;

    ttscommit;
}

private void findOrCreateMCRPriceHistory(SalesLine _salesLine, Common _common)
{
    MCRPriceHistory mcrPriceHistory;
    Version version;

    select firstonly mcrPriceHistory order by Version desc
            where mcrPriceHistory.RefRecId     == _common.RecId
            && mcrPriceHistory.RefTableId   == _common.TableId;

    if (!mcrPriceHistory || !mcrPriceHistory.equal(_common))
    {
        version = mcrPriceHistory.Version + 1;

        mcrPriceHistory.clear();

        mcrPriceHistory.Version = version;
        mcrPriceHistory.initFrom(_common);

        if (mcrPriceHistory.validateWrite())
        {
            mcrPriceHistory.insert();
        }
    }

    setFoundPriceHistoryRecId.add(tableId2Name(_common.TableId), mcrPriceHistory.RecId);
}

private void updateBasePriceHistory(Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine _crtPriceLine, SalesLine _salesLine)
{
    GUPItemBasePrice gupItemBasePrice;

    select firstonly gupItemBasePrice
        where gupItemBasePrice.RecId    == _crtPriceLine.get_RecordId()
           && gupItemBasePrice.ItemId   == _salesLine.ItemId;

    if (!gupItemBasePrice)
    {
        InventTableModule   inventTableModule;

        // Find default item sales price
        inventTableModule = InventTableModule::find(_salesLine.ItemId, ModuleInventPurchSales::Sales);

        if (inventTableModule)
        {
            this.findOrCreateMCRPriceHistory(_salesLine, inventTableModule);
        }
    }
}

private void updateTradeAgreementHistory(Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine _crtPriceLine, SalesLine _salesLine)
{
    PriceDiscTable priceDiscTable = PriceDiscTable::findRecId(_crtPriceLine.get_RecordId());
    if (priceDiscTable)
    {
        this.findOrCreateMCRPriceHistory(_salesLine, priceDiscTable);
    }
}

private void updateGUPMarginComponentAdjustmentHistory(Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine _crtPriceLine, SalesLine _salesLine)
{
    //Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine adjustmentPriceLine = _crtPriceLine as Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine;

    RetailPeriodicDiscount  periodicDiscount;
    RetailPeriodicDiscountLine periodicDiscountLine;
    GUPPriceComponentCodeSetup marginComponentSetup;

    select firstonly marginComponentSetup
        order by marginComponentSetup.CalculationSequence
        join periodicDiscount
            where marginComponentSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
        join periodicDiscountLine
        where periodicDiscount.OfferId              == periodicDiscountLine.OfferId &&
              periodicDiscountLine.recId            == _crtPriceLine.get_RecordId() &&
              periodicDiscount.Status               == RetailDisabledEnabled::Enabled &&
              periodicDiscount.IsGupDiscount        == NoYes::Yes &&
              periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion;

    if (periodicDiscount)
    {
        GUPMarginComponentAdjustmentHistory   marginComponentAdjustmentHistory;
        marginComponentAdjustmentHistory.clear();
        marginComponentAdjustmentHistory.SalesLine = _salesLine.RecId;
        marginComponentAdjustmentHistory.MarginComponentCode = periodicDiscount.PriceComponentCodeName;
        marginComponentAdjustmentHistory.marginComponentAdjustment = periodicDiscount.OfferId;
        marginComponentAdjustmentHistory.CalculationSequence = marginComponentSetup.CalculationSequence;
        marginComponentAdjustmentHistory.Amount = _crtPriceLine.get_Value();
        //marginComponentAdjustmentHistory.Amount = adjustmentPriceLine.get_AdjustedAmount();
        marginComponentAdjustmentHistory.insert();
    }
}

private void UpdateGUPPriceAdjustmentHistory(Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction crtSalesTransaction , str crtLineIdCurrentLine = '')
{
    if (crtSalesTransaction != null)
    {
        setFoundPriceHistoryRecId = new Map(Types::String, Types::Int64);

        ttsBegin;

        CLRObject clrSalesLines, enumeratorSalesLine;
        CLRObject clrPriceLines, enumeratorPriceLine;
        SalesLine salesLine;
        str lineId;

        clrSalesLines = crtSalesTransaction.get_SalesLines();
        enumeratorSalesLine = clrSalesLines.GetEnumerator();
        while (enumeratorSalesLine.MoveNext())
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = enumeratorSalesLine.get_Current();
            salesLine = SalesLine::findInventTransId(crtSalesLine.get_LineId());
            lineId = crtSalesLine.get_LineId();

            if (crtLineIdCurrentLine && crtLineIdCurrentLine != lineId)
            {
                continue;
            }

            if (salesLine.SalesStatus != SalesStatus::Invoiced && salesLine.SalesStatus != SalesStatus::Canceled)
            {
                // First delete all margin adjustment history
                GUPMarginComponentAdjustmentHistory::deleteHistory(salesLine.RecId);

                // Second delete all price agreement history
                this.deleteMCRPriceHistory(salesLine);

                boolean hasTradeAgreement;

                Microsoft.Dynamics.Commerce.Runtime.DataModel.BasePriceLine basePriceLine;
                Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreementPriceLine tradeAgreementPriceLine;

                clrPriceLines = crtSalesLine.get_PriceLines();
                enumeratorPriceLine = clrPriceLines.GetEnumerator();
                while (enumeratorPriceLine.MoveNext())
                {
                    Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceLine crtPriceLine = enumeratorPriceLine.get_Current();

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.BasePriceLine)
                    {
                        this.updateBasePriceHistory(crtPriceLine, salesLine);
                    }

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreementPriceLine)
                    {
                        hasTradeAgreement = true;
                        this.updateTradeAgreementHistory(crtPriceLine, salesLine);
                    }

                    if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentPriceLine)
                    //if (crtPriceLine is Microsoft.Dynamics.Commerce.Runtime.DataModel.GlobalUnifiedPricingAdjustmentPriceLine)
                    {
                        this.updateGUPMarginComponentAdjustmentHistory(crtPriceLine, salesLine);
                    }
                }

                if (hasTradeAgreement)
                {
                    if (setFoundPriceHistoryRecId.exists(tableStr(InventTableModule)))
                    {
                        setFoundPriceHistoryRecId.remove(tableStr(InventTableModule));
                    }
                }

                MapEnumerator mapEnumeratorReferences;
                mapEnumeratorReferences = setFoundPriceHistoryRecId.getEnumerator();

                while (mapEnumeratorReferences.moveNext())
                {
                    if (!MCRPriceHistoryRef::exists(mapEnumeratorReferences.currentValue(), salesLine.mcrOrderLine2PriceHistoryRef))
                    {
                        MCRPriceHistoryRef mcrPriceHistoryRef;

                        mcrPriceHistoryRef.clear();
                        mcrPriceHistoryRef.PriceHistoryRecId = mapEnumeratorReferences.currentValue();
                        mcrPriceHistoryRef.MCROrderLine2PriceHistoryRef = salesLine.mcrOrderLine2PriceHistoryRef;
                        mcrPriceHistoryRef.insert();
                    }
                }
            }
        }

        ttscommit;
    }
}
